void RenderTools(Server item)
{
    foreach (var tool in item.Tools)
    {
        var toggle = K.Toggle(tool.Name, tool.Enabled, on =>
        {
            tool.Enabled = on;
            RefreshMeter();       // 预算条与合计随之变化
            status.Text = $"{tool.Name} {(on ? "enabled" : "disabled")} for {item.Name}. Simulated.";
        });
        toolRows.Children.Add(K.Row(8, toggle, K.Caption(tool.Description)));
    }
}

